CREATE TABLE "players" ("id" SERIAL PRIMARY KEY, "public_id" UUID NOT NULL UNIQUE, "name" VARCHAR(160) NOT NULL, "nationality" VARCHAR(80), "birth_date" DATE, "position" VARCHAR(40), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "player_team_memberships" ("id" SERIAL PRIMARY KEY, "player_id" INTEGER NOT NULL REFERENCES "players"("id") ON DELETE RESTRICT, "team_id" INTEGER NOT NULL REFERENCES "teams"("id") ON DELETE RESTRICT, "start_date" DATE NOT NULL, "end_date" DATE, "shirt_number" INTEGER, CONSTRAINT "membership_dates" CHECK ("end_date" IS NULL OR "end_date" >= "start_date"));
CREATE INDEX "membership_player_date_idx" ON "player_team_memberships"("player_id", "start_date");
CREATE INDEX "membership_team_idx" ON "player_team_memberships"("team_id");
CREATE TABLE "match_lineup_players" ("id" SERIAL PRIMARY KEY, "match_id" INTEGER NOT NULL REFERENCES "matches"("id") ON DELETE RESTRICT, "team_id" INTEGER NOT NULL REFERENCES "teams"("id") ON DELETE RESTRICT, "player_id" INTEGER NOT NULL REFERENCES "players"("id") ON DELETE RESTRICT, "starter" BOOLEAN NOT NULL DEFAULT false, "captain" BOOLEAN NOT NULL DEFAULT false, "position" VARCHAR(40), CONSTRAINT "lineup_match_player_unique" UNIQUE("match_id","player_id"));
CREATE INDEX "lineup_team_idx" ON "match_lineup_players"("team_id");
CREATE TABLE "team_match_statistics" ("id" SERIAL PRIMARY KEY, "match_id" INTEGER NOT NULL REFERENCES "matches"("id") ON DELETE RESTRICT, "team_id" INTEGER NOT NULL REFERENCES "teams"("id") ON DELETE RESTRICT, "metric" VARCHAR(60) NOT NULL, "value" DOUBLE PRECISION NOT NULL, CONSTRAINT "team_stat_unique" UNIQUE("match_id","team_id","metric"));
CREATE TABLE "player_match_statistics" ("id" SERIAL PRIMARY KEY, "match_id" INTEGER NOT NULL REFERENCES "matches"("id") ON DELETE RESTRICT, "player_id" INTEGER NOT NULL REFERENCES "players"("id") ON DELETE RESTRICT, "metric" VARCHAR(60) NOT NULL, "value" DOUBLE PRECISION NOT NULL, CONSTRAINT "player_stat_unique" UNIQUE("match_id","player_id","metric"));
